"""Minimal status reconciliation; reread each shared document immediately before editing."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
def paragraph(relative,prefix,replacement):
    path=ROOT/relative
    text=path.read_text(encoding='utf-8')
    rows=text.splitlines(keepends=True)
    matches=[i for i,row in enumerate(rows) if row.startswith(prefix)]
    assert len(matches)==1,(relative,prefix,matches)
    rows[matches[0]]=replacement+'\n'
    path.write_text(''.join(rows),encoding='utf-8')

